import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.BveOjhN0.js";const h=JSON.parse('{"title":"Product Roadmap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Product Roadmap | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/getting-started/product-roadmap"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Product Roadmap | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/getting-started/product-roadmap"}]]},"headers":[],"relativePath":"getting-started/product-roadmap.md","filePath":"getting-started/product-roadmap.md","lastUpdated":1785703811000}'),o={name:"getting-started/product-roadmap.md"};function d(n,e,s,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="product-roadmap" tabindex="-1">Product Roadmap <a class="header-anchor" href="#product-roadmap" aria-label="Permalink to &quot;Product Roadmap&quot;">​</a></h1><p>Long-term direction of the platform: evolution from a CRM into a complete SaaS ERP. Modules should be implemented in the order below unless business priorities require otherwise.</p><blockquote><p><strong>Architecture Policy</strong></p><p>The platform foundation (authentication, tenancy, RBAC, billing, marketplace, settings, audit logging, and module licensing) is <strong>frozen</strong>. New functionality must be implemented as modules using the <a href="/architecture/module-architecture">Module Architecture</a> convention and the <a href="/developer-guide/module-development">Module Development Standard</a>. Architectural changes should only be made for critical security issues, production defects, or platform-wide improvements.</p><p>See <a href="/getting-started/platform-freeze">architecture/platform-freeze.md</a>.</p></blockquote><hr><h2 id="phase-1-—-crm-completed-in-progress" tabindex="-1">Phase 1 — CRM (Completed / In Progress) <a class="header-anchor" href="#phase-1-—-crm-completed-in-progress" aria-label="Permalink to &quot;Phase 1 — CRM (Completed / In Progress)&quot;">​</a></h2><p>The CRM is the foundation of the platform and is the first functional area delivered.</p><h3 id="completed" tabindex="-1">Completed <a class="header-anchor" href="#completed" aria-label="Permalink to &quot;Completed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module / capability</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/leads-overview">Leads</a></td><td>✅ Completed (Sprint 2 UX + inbound Custom Webhook + Meta Lead Ads ingest)</td></tr><tr><td><a href="/user-guide/contacts-overview">Contacts</a></td><td>✅ Completed (directory, assignment, notes/activity timeline; unlocks full lead convert)</td></tr><tr><td><a href="/user-guide/companies-overview">Companies</a></td><td>✅ Completed (organizations directory, assignment, notes/activity timeline; Contact <code>company_id</code> link)</td></tr><tr><td><a href="/user-guide/tasks-overview">Tasks</a></td><td>✅ Completed (Sprint 2 UX: board, KPIs, waiting status, due-date permission, comments/history)</td></tr><tr><td><a href="/user-guide/todos-overview">ToDos</a></td><td>✅ Completed (personal creator-scoped checklists; board + list; owner view-all; creator-only delete)</td></tr><tr><td>In-app notifications + Reverb</td><td>✅ Completed (payload v1, NotificationBatch digests, Reverb/Echo, modular registry, browser toasts; poll fallback only)</td></tr><tr><td>Tenant dashboard widgets</td><td>✅ Completed (module/permission/assignee scoped; includes Calendar upcoming when entitled)</td></tr><tr><td><a href="/user-guide/communication-templates">Communication Templates</a></td><td>✅ Completed (plain-text templates, placeholder registry, WhatsApp <code>wa.me</code> from Leads; migrate-only production registration)</td></tr><tr><td><a href="/user-guide/calendar-overview">Calendar</a></td><td>✅ Completed (Week/Day time grids + DnD, Month/Agenda, view_all oversight, upcoming widget)</td></tr><tr><td><a href="/user-guide/meetings-overview">Meetings</a></td><td>✅ Completed (host/invitees, Zoom/Google Meet OAuth, reminders, Calendar projection, completion)</td></tr><tr><td><a href="/user-guide/activities-overview">Activities</a></td><td>✅ Completed (loggable call/email/note/follow-up engagements; Contact/Company/Lead links; complete + timeline mirrors)</td></tr><tr><td><strong>Lead Source Driver Architecture</strong></td><td>✅ Implemented (<a href="/developer-guide/lead-source-driver-architecture">standard</a>; Custom Webhook + Meta drivers shipped)</td></tr><tr><td><strong>Meta Lead Ads Integration</strong></td><td>✅ Shipped (<a href="/developer-guide/meta-app-setup">Meta App Setup</a> · <a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads</a>)</td></tr></tbody></table><h4 id="calendar-shipped" tabindex="-1">Calendar (shipped) <a class="header-anchor" href="#calendar-shipped" aria-label="Permalink to &quot;Calendar (shipped)&quot;">​</a></h4><ul><li>Personal events; Week (default) / Day / Month / Agenda</li><li>Drag-and-drop reschedule on Week/Day; workspace timezone-aware UI</li><li>Upcoming events dashboard widget</li><li>Org-wide view via <code>calendar.view_all</code> (no calendar assignment)</li></ul><h4 id="meetings-shipped" tabindex="-1">Meetings (shipped) <a class="header-anchor" href="#meetings-shipped" aria-label="Permalink to &quot;Meetings (shipped)&quot;">​</a></h4><ul><li>Meetings scheduling with host + invitees (internal and external email guests)</li><li>Workspace Zoom and Google Meet OAuth connections</li><li>One reminder before start (in-app, web push, email) for creator, host, and invitees</li><li>Projects onto Calendar via <code>CalendarEventService::upsertFromSource</code></li></ul><blockquote><p><strong>Dependency:</strong> Meetings → Calendar (required). See <a href="/architecture/module-dependencies">Module Dependencies</a> and <a href="/user-guide/meetings-overview">Meetings</a>.</p></blockquote><h4 id="activities-shipped" tabindex="-1">Activities (shipped) <a class="header-anchor" href="#activities-shipped" aria-label="Permalink to &quot;Activities (shipped)&quot;">​</a></h4><ul><li>Loggable CRM engagements: call, email, note, follow-up, other</li><li>Link to Contact / Company / Lead (at least one; soft entitlement)</li><li>Due date, complete action, assignee scoping, notes + timeline</li><li>Mirrors create/complete onto related record timelines</li><li>Recent Activities dashboard widget</li></ul><h3 id="planned" tabindex="-1">Planned <a class="header-anchor" href="#planned" aria-label="Permalink to &quot;Planned&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module / capability</th><th>Status</th></tr></thead><tbody><tr><td><strong>WhatsApp Cloud Integration</strong></td><td>Planned (docs blueprint only — <a href="/developer-guide/whatsapp-cloud-integration">Cloud API beyond <code>wa.me</code></a>)</td></tr></tbody></table><p><strong>Goal:</strong> Provide a complete customer relationship management experience with lead tracking, task management, customer records, scheduling, meetings, and activity history.</p><hr><h2 id="phase-2-—-sales" tabindex="-1">Phase 2 — Sales <a class="header-anchor" href="#phase-2-—-sales" aria-label="Permalink to &quot;Phase 2 — Sales&quot;">​</a></h2><p>Once CRM is complete, extend it into a full sales workflow.</p><table tabindex="0"><thead><tr><th>Module</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/opportunities-overview">Opportunities</a></td><td>✅ Completed (deals, stages, Kanban board + table, soft Contact/Company/Lead links; free Sales opt-in)</td></tr><tr><td>Sales Pipeline</td><td>✅ Delivered with Opportunities (stages + board inside the module — <strong>not</strong> a separate Marketplace SKU)</td></tr><tr><td><a href="/user-guide/quotations-overview">Quotations</a></td><td>✅ Completed (line items with computed totals, status workflow, required Opportunity link; free Sales opt-in)</td></tr><tr><td><a href="/user-guide/contracts-overview">Contracts</a></td><td>✅ Completed (agreement tracking, status workflow, required Opportunity link, optional Quotation link; free Sales opt-in)</td></tr></tbody></table><h4 id="opportunities-shipped" tabindex="-1">Opportunities (shipped) <a class="header-anchor" href="#opportunities-shipped" aria-label="Permalink to &quot;Opportunities (shipped)&quot;">​</a></h4><ul><li>Deal amount / currency / probability / expected close date</li><li>Seeded pipeline: Prospecting → Qualification → Proposal → Negotiation → Won / Lost</li><li>Kanban board + table; KPIs (pipeline value, weighted, conversion)</li><li>Soft optional links to Contacts, Companies, Leads</li><li>Notes, assignment, domain timeline; free Marketplace opt-in under category <code>sales</code></li></ul><h4 id="quotations-shipped" tabindex="-1">Quotations (shipped) <a class="header-anchor" href="#quotations-shipped" aria-label="Permalink to &quot;Quotations (shipped)&quot;">​</a></h4><ul><li>Required Opportunity link; optional Contact/Company links</li><li>Line items (description, quantity, unit price, tax rate) with server-computed subtotal / tax / total</li><li>Status workflow: <code>draft → sent → accepted|rejected|expired</code></li><li>Notes, assignment, domain timeline; <strong>hard dependency</strong> on Opportunities; free Marketplace opt-in under category <code>sales</code></li></ul><h4 id="contracts-shipped" tabindex="-1">Contracts (shipped) <a class="header-anchor" href="#contracts-shipped" aria-label="Permalink to &quot;Contracts (shipped)&quot;">​</a></h4><ul><li>Required Opportunity link; optional Quotation link (only when Quotations is entitled)</li><li>Party name, start/end dates, value/currency</li><li>Status workflow: <code>draft → active → expired|terminated</code></li><li>Notes, assignment, domain timeline; <strong>hard dependency</strong> on Opportunities; free Marketplace opt-in under category <code>sales</code></li></ul><p><strong>Goal:</strong> Manage the entire sales lifecycle from opportunity creation through quotation, negotiation, and contract execution. ✅ <strong>Achieved</strong> — Opportunities, Quotations, and Contracts are all shipped.</p><hr><h2 id="phase-3-—-billing" tabindex="-1">Phase 3 — Billing <a class="header-anchor" href="#phase-3-—-billing" aria-label="Permalink to &quot;Phase 3 — Billing&quot;">​</a></h2><p>Build a comprehensive billing and invoicing solution that integrates with the existing Marketplace and subscription platform.</p><table tabindex="0"><thead><tr><th>Module</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/invoices-overview">Invoices</a></td><td>✅ Completed (line items with computed totals, status workflow, optional Contact/Company/Quotation links; free Billing opt-in)</td></tr><tr><td><a href="/user-guide/estimates-overview">Estimates</a></td><td>✅ Completed (pre-sale cost estimates, line items, status workflow, convert-to-invoice; free Billing opt-in, requires Invoices)</td></tr><tr><td><a href="/user-guide/credit-notes-overview">Credit Notes</a></td><td>✅ Completed (credit notes against invoices, line items, issue/apply/void workflow, apply credits <code>amount_credited</code> + <code>balance_due</code>; free Billing opt-in, requires Invoices)</td></tr><tr><td><a href="/user-guide/payments-overview">Payments</a></td><td>✅ Completed (record customer payments, allocate to invoices, post/void drives invoice balance + status; free Billing opt-in, requires Invoices)</td></tr></tbody></table><h4 id="invoices-shipped" tabindex="-1">Invoices (shipped) <a class="header-anchor" href="#invoices-shipped" aria-label="Permalink to &quot;Invoices (shipped)&quot;">​</a></h4><ul><li>No hard <code>module_dependencies</code> row — installs standalone (unlike Quotations/Contracts, which require Opportunities)</li><li>Optional Contact/Company links and optional Quotation link (only when their module is entitled)</li><li>Line items (description, quantity, unit price, tax rate) with server-computed subtotal / tax / total</li><li>Balance fields (<code>amount_paid</code>, <code>amount_credited</code>, <code>balance_due</code>) driven by the Payments module — read-only via this API</li><li>Status workflow: <code>draft → sent → partial|paid → void</code> (<code>send</code> / <code>void</code> / <code>status</code> actions)</li><li>Notes, assignment, domain timeline; free Marketplace opt-in under category <code>billing</code></li></ul><h4 id="payments-shipped" tabindex="-1">Payments (shipped) <a class="header-anchor" href="#payments-shipped" aria-label="Permalink to &quot;Payments (shipped)&quot;">​</a></h4><ul><li><strong>Hard <code>module_dependencies</code> row on Invoices</strong> — the first Phase 3 module to require another; Marketplace blocks install until Invoices is entitled</li><li>Payment fields (amount, currency, method, paid-at, reference, notes) plus allocations against one or more invoices</li><li>Status workflow: <code>draft → posted → void</code> — posting applies allocations to invoice <code>amount_paid</code> and recalculates invoice balance/status; voiding reverses them</li><li>Optional Contact/Company links, assignment, notes, domain timeline; free Marketplace opt-in under category <code>billing</code></li><li><code>amount_credited</code> is not touched by Payments — see Credit Notes below</li></ul><h4 id="credit-notes-shipped" tabindex="-1">Credit Notes (shipped) <a class="header-anchor" href="#credit-notes-shipped" aria-label="Permalink to &quot;Credit Notes (shipped)&quot;">​</a></h4><ul><li><strong>Hard <code>module_dependencies</code> row on Invoices</strong> — same pattern as Payments; Marketplace blocks install until Invoices is entitled</li><li>Credit note fields (title, notes, currency, issue date) plus line items (description, quantity, unit price, tax rate) with server-computed subtotal / tax / total</li><li>Status workflow: <code>draft → issued → applied</code>, with <code>void</code> available from <code>draft</code> or <code>issued</code> — applying adds the credit note&#39;s total to the invoice&#39;s <code>amount_credited</code> and recalculates <code>balance_due</code> (does not change invoice <code>status</code>)</li><li>Optional Contact/Company links, assignment, notes, domain timeline; free Marketplace opt-in under category <code>billing</code></li></ul><h4 id="estimates-shipped" tabindex="-1">Estimates (shipped) <a class="header-anchor" href="#estimates-shipped" aria-label="Permalink to &quot;Estimates (shipped)&quot;">​</a></h4><ul><li><strong>Hard <code>module_dependencies</code> row on Invoices</strong> — same pattern as Payments/Credit Notes; Marketplace blocks install until Invoices is entitled</li><li>Estimate fields (title, notes, currency, valid-until) plus line items (description, quantity, unit price, tax rate) with server-computed subtotal / tax / total</li><li>Optional Contact/Company links, plus optional Opportunity/Quotation links (each validated only when that module is entitled)</li><li>Status workflow: <code>draft → sent → accepted|rejected|expired</code> (identical shape to Quotations)</li><li><strong>Convert to invoice</strong> (<code>POST /estimates/{id}/convert</code>) — creates a draft <code>CustomerInvoice</code> with a copy of the estimate&#39;s lines, links it back via <code>customer_invoices.estimate_id</code>, and marks the estimate <code>accepted</code>; one-way and one-time per estimate</li><li>Assignment, notes, domain timeline; free Marketplace opt-in under category <code>billing</code></li></ul><p><strong>Goal:</strong> Provide complete customer billing, payment tracking, and financial document management. ✅ <strong>Achieved</strong> — Invoices, Payments, Credit Notes, and Estimates are all shipped, completing Phase 3.</p><blockquote><p><strong>Note:</strong> Platform billing (module subscriptions, consolidated billing, gateway abstraction) already exists under Central. Phase 3 modules are <strong>tenant product billing</strong> (customer-facing invoices/payments), not a redesign of the Marketplace billing engine.</p></blockquote><hr><h2 id="phase-4-—-purchasing" tabindex="-1">Phase 4 — Purchasing <a class="header-anchor" href="#phase-4-—-purchasing" aria-label="Permalink to &quot;Phase 4 — Purchasing&quot;">​</a></h2><p>Introduce purchasing and vendor management. New category: <code>purchasing</code> (<strong>Purchasing</strong>), <code>category_sort_order = 40</code>. ✅ <strong>Achieved</strong> — Vendors, Purchase Orders, and Expenses are all shipped, completing Phase 4.</p><table tabindex="0"><thead><tr><th>Module</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/vendors-overview">Vendors</a></td><td>✅ Completed (supplier directory, assignment, notes/activity timeline, status; free Purchasing opt-in)</td></tr><tr><td><a href="/user-guide/purchase-orders-overview">Purchase Orders</a></td><td>✅ Completed (header + lines, required vendor link, status workflow, assignment, notes/activity timeline, convert to expense; free Purchasing opt-in)</td></tr><tr><td><a href="/user-guide/expenses-overview">Expenses</a></td><td>✅ Completed (single-amount MVP, optional vendor/PO links, status workflow, assignment, notes/activity timeline; free Purchasing opt-in)</td></tr></tbody></table><h4 id="vendors-shipped" tabindex="-1">Vendors (shipped) <a class="header-anchor" href="#vendors-shipped" aria-label="Permalink to &quot;Vendors (shipped)&quot;">​</a></h4><ul><li>Name, email, phone, website, address, tax ID, payment terms, currency, status (<code>active</code>/<code>inactive</code>)</li><li>No <code>contacts</code> relationship — first-class, standalone supplier record (unlike Companies)</li><li>Assignment, notes, domain timeline; free Marketplace opt-in under category <code>purchasing</code></li><li>KPIs: total, my vendors, unassigned, active, inactive</li></ul><h4 id="purchase-orders-shipped" tabindex="-1">Purchase Orders (shipped) <a class="header-anchor" href="#purchase-orders-shipped" aria-label="Permalink to &quot;Purchase Orders (shipped)&quot;">​</a></h4><ul><li>Required Vendor link (<strong>hard dependency</strong> — Marketplace blocks install until Vendors is entitled)</li><li>Line items (description, quantity, unit price, tax rate) with server-computed subtotal / tax / total</li><li>Status workflow: <code>draft → sent → partially_received|received|cancelled</code> (also <code>sent → cancelled</code>, <code>partially_received → received|cancelled</code>)</li><li><code>partially_received</code> is acknowledgement-only; a fully received PO posts stock-in for product-linked stock-tracked lines when Products and Inventory are entitled</li><li>Convert to Expense (<code>POST /purchase-orders/{id}/convert</code>) — one-way, one-time, gated by a <strong>soft</strong> (call-time) check that the Expenses module is entitled, not a hard <code>module_dependencies</code> row</li><li>Notes, assignment, domain timeline; free Marketplace opt-in under category <code>purchasing</code></li></ul><h4 id="expenses-shipped" tabindex="-1">Expenses (shipped) <a class="header-anchor" href="#expenses-shipped" aria-label="Permalink to &quot;Expenses (shipped)&quot;">​</a></h4><ul><li>No hard <code>module_dependencies</code> — installs standalone; optional Vendor and Purchase Order links are <strong>soft dependencies</strong>, validated only when those modules are entitled</li><li>Single-amount MVP — no line items, receipts, reimbursements, or GL posting</li><li>Fields: number (<code>EXP-</code> prefix), title, category (<code>travel</code>/<code>office</code>/<code>software</code>/<code>utilities</code>/<code>other</code>), amount, tax amount, currency, expense date, notes</li><li>Status workflow: <code>draft → submitted → approved|rejected</code>, <code>approved → paid</code>, <code>draft|submitted → cancelled</code></li><li>Draft-only field edits; workflow actions (<code>submit</code>/<code>approve</code>/<code>reject</code>/<code>pay</code>/<code>cancel</code>) available regardless of edit-lock</li><li>Notes, assignment, domain timeline; free Marketplace opt-in under category <code>purchasing</code></li></ul><p><strong>Goal:</strong> Manage supplier relationships, procurement workflows, and operational expenses. ✅ <strong>Achieved.</strong></p><hr><h2 id="phase-5-—-inventory" tabindex="-1">Phase 5 — Inventory <a class="header-anchor" href="#phase-5-—-inventory" aria-label="Permalink to &quot;Phase 5 — Inventory&quot;">​</a></h2><p>Implement inventory and warehouse management. ✅ <strong>Achieved</strong> — Products, Warehouses, and Inventory are all shipped.</p><table tabindex="0"><thead><tr><th>Module</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/products-overview">Products</a> (including Categories)</td><td>✅ Completed (catalog, categories, stock-tracking settings, notes/activity; free Inventory opt-in)</td></tr><tr><td><a href="/user-guide/warehouses-overview">Warehouses</a></td><td>✅ Completed (locations, default <code>MAIN</code>, notes/activity; free Inventory opt-in)</td></tr><tr><td><a href="/user-guide/inventory-overview">Inventory</a> — Stock Management</td><td>✅ Completed (levels, movement ledger, controlled in/out/adjust changes; hard-depends on Products)</td></tr><tr><td><a href="/user-guide/inventory-overview">Inventory</a> — Stock Transfers</td><td>✅ Completed (draft → in transit → completed/cancelled; posts stock on completion)</td></tr></tbody></table><h4 id="products-shipped" tabindex="-1">Products (shipped) <a class="header-anchor" href="#products-shipped" aria-label="Permalink to &quot;Products (shipped)&quot;">​</a></h4><ul><li>SKU catalog with categories, unit/cost/price/currency, status, optional reorder level, and stock-tracking flag</li><li>Optional <code>product_id</code> on Purchase Order lines; only stock-tracked linked products post receipt stock</li><li>Notes, domain activity, soft delete/restore; free Marketplace opt-in under category <code>inventory</code></li></ul><h4 id="warehouses-shipped" tabindex="-1">Warehouses (shipped) <a class="header-anchor" href="#warehouses-shipped" aria-label="Permalink to &quot;Warehouses (shipped)&quot;">​</a></h4><ul><li>Tenant locations with active/default status; <code>ensureDefaultWarehouse()</code> provides <code>MAIN</code> when required</li><li>The sole default warehouse cannot be deleted</li><li>Notes, domain activity, soft delete/restore; free Marketplace opt-in under category <code>inventory</code></li></ul><h4 id="inventory-shipped" tabindex="-1">Inventory (shipped) <a class="header-anchor" href="#inventory-shipped" aria-label="Permalink to &quot;Inventory (shipped)&quot;">​</a></h4><ul><li>Per-product/per-warehouse levels, movement history, low-stock visibility, and non-negative transactional posting</li><li>Adjustments (<code>in</code>, <code>out</code>, <code>adjust</code>) and transfers (<code>draft → in_transit → completed|cancelled</code>)</li><li>Completing a transfer posts paired movements; a received Purchase Order posts stock-in once for product-linked stock-tracked lines when Products and Inventory are entitled</li></ul><p><strong>Goal:</strong> Provide inventory control, stock tracking, warehouse operations, and product management. ✅ <strong>Achieved.</strong></p><hr><h2 id="phase-6-—-finance" tabindex="-1">Phase 6 — Finance <a class="header-anchor" href="#phase-6-—-finance" aria-label="Permalink to &quot;Phase 6 — Finance&quot;">​</a></h2><p>Expand into accounting and financial reporting.</p><table tabindex="0"><thead><tr><th>Marketplace SKU</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/accounting-overview">Accounting</a></td><td>✅ Completed (CoA, journals draft/post/void, GL inquiry; free Finance opt-in)</td></tr><tr><td><a href="/user-guide/financial-reports-overview">Financial Reports</a></td><td>✅ Completed (Trial Balance, P&amp;L, Balance Sheet; hard-depends on Accounting)</td></tr></tbody></table><h4 id="capabilities-inside-the-skus-—-not-separate-marketplace-modules" tabindex="-1">Capabilities (inside the SKUs — not separate Marketplace modules) <a class="header-anchor" href="#capabilities-inside-the-skus-—-not-separate-marketplace-modules" aria-label="Permalink to &quot;Capabilities (inside the SKUs — not separate Marketplace modules)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Capability</th><th>Lives in</th></tr></thead><tbody><tr><td>Accounts (chart of accounts)</td><td>Accounting</td></tr><tr><td>Journals</td><td>Accounting</td></tr><tr><td>General Ledger inquiry</td><td>Accounting</td></tr><tr><td>Financial Reports (TB / P&amp;L / BS)</td><td>Financial Reports</td></tr></tbody></table><p><strong>Goal:</strong> Provide the financial backbone required for a complete ERP solution. ✅ <strong>Achieved</strong> for the manual double-entry MVP (single currency; no auto-post from Billing/Purchasing/Inventory yet).</p><hr><h2 id="phase-7-—-human-resources" tabindex="-1">Phase 7 — Human Resources <a class="header-anchor" href="#phase-7-—-human-resources" aria-label="Permalink to &quot;Phase 7 — Human Resources&quot;">​</a></h2><p>Implement workforce management.</p><table tabindex="0"><thead><tr><th>Marketplace SKU</th><th>Status</th></tr></thead><tbody><tr><td><a href="/user-guide/employees-overview">Employees</a></td><td>✅ Completed (directory, employment type/status, optional user link; free HR opt-in)</td></tr><tr><td><a href="/user-guide/leave-management-overview">Leave Management</a></td><td>✅ Completed (types, balances, request workflow; hard-depends on Employees)</td></tr><tr><td><a href="/user-guide/attendance-overview">Attendance</a></td><td>✅ Completed (daily records, check-in/out, presence status; hard-depends on Employees)</td></tr><tr><td><a href="/user-guide/payroll-overview">Payroll</a></td><td>✅ Completed (profiles, pay runs draft/approve/pay, optional Accounting journal post; hard-depends on Employees)</td></tr></tbody></table><h4 id="capabilities-inside-the-skus-—-not-separate-marketplace-modules-1" tabindex="-1">Capabilities (inside the SKUs — not separate Marketplace modules) <a class="header-anchor" href="#capabilities-inside-the-skus-—-not-separate-marketplace-modules-1" aria-label="Permalink to &quot;Capabilities (inside the SKUs — not separate Marketplace modules)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Capability</th><th>Lives in</th></tr></thead><tbody><tr><td>Employee directory</td><td>Employees</td></tr><tr><td>Leave types / balances / requests</td><td>Leave Management</td></tr><tr><td>Daily attendance records</td><td>Attendance</td></tr><tr><td>Payroll profiles</td><td>Payroll</td></tr><tr><td>Pay runs (approve / pay / post)</td><td>Payroll</td></tr></tbody></table><p><strong>Goal:</strong> Provide employee management, attendance tracking, leave workflows, and payroll processing. ✅ <strong>Achieved</strong> for the HR MVP (no tax engine, biometric integrations, or accrual policies yet).</p><hr><h2 id="future-expansion" tabindex="-1">Future Expansion <a class="header-anchor" href="#future-expansion" aria-label="Permalink to &quot;Future Expansion&quot;">​</a></h2><p>The platform architecture supports additional modules without requiring architectural refactoring. Candidates include:</p><ul><li>Assets</li><li>Projects</li><li>Help Desk</li><li>Knowledge Base</li><li>Documents</li><li>Manufacturing</li><li>Quality Assurance</li><li>Recruitment</li><li>Customer Portal</li><li>Vendor Portal</li><li>Business Intelligence &amp; Analytics</li><li>Workflow Automation</li><li>Marketing Automation</li><li>Email Campaigns</li><li>SMS &amp; WhatsApp provider integrations (Cloud API / Twilio) — templates + <code>wa.me</code> MVP already shipped; Cloud API blueprint: <a href="/developer-guide/whatsapp-cloud-integration">WhatsApp Cloud Integration</a></li><li>API &amp; Webhooks</li><li><strong>AI Integration (Planning)</strong> — optional integrations with Leads, Tasks, CRM, and other domain modules</li><li>Multi-Branch Management</li><li>Multi-Currency Accounting</li><li>POS (Point of Sale)</li><li>E-Commerce Integrations</li></ul><h3 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>AI Integration (Planning)</td><td>Planned</td></tr></tbody></table><p>AI is documented as a future cross-cutting capability. Integrations with Leads, Tasks, CRM, and similar modules should be <strong>optional</strong>. See <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><p>These modules will follow the same <a href="/architecture/module-architecture">Module Architecture</a> and <a href="/developer-guide/module-development">Module Development Standard</a> established by Leads and Tasks.</p><hr><h2 id="multi-provider-email-delivery" tabindex="-1">Multi-Provider Email Delivery <a class="header-anchor" href="#multi-provider-email-delivery" aria-label="Permalink to &quot;Multi-Provider Email Delivery&quot;">​</a></h2><p>Platform-wide capability (Central + Tenant). Today outgoing mail is <strong>SMTP-centric</strong> (Central defaults with optional tenant SMTP override). The roadmap evolves that into a <strong>provider-agnostic delivery architecture</strong> so SMTP is one driver among many — not the core design.</p><p>This is a <strong>platform infrastructure</strong> improvement (settings, mail transport, logging, ops), not a Marketplace-licensed business module. Implementation must extend the existing settings hierarchy and runtime config overlay; it must not redesign the frozen foundation.</p><table tabindex="0"><thead><tr><th>Status label</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Shipped</strong></td><td>Implemented in the platform</td></tr><tr><td><strong>Future</strong></td><td>Follow-on reliability, observability, and provider-specific features</td></tr><tr><td><strong>Enterprise</strong></td><td>Advanced multi-provider routing and ops for large deployments</td></tr></tbody></table><h3 id="email-transport-abstraction-shipped" tabindex="-1">Email transport abstraction (Shipped) <a class="header-anchor" href="#email-transport-abstraction-shipped" aria-label="Permalink to &quot;Email transport abstraction (Shipped)&quot;">​</a></h3><p><code>EmailManager</code> resolves an <code>EmailDriverInterface</code> implementation from the active configuration. Application code (notifications, mailables, invites, password resets, digests) continues to send through Laravel Mail — the manager applies the active provider at runtime.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><code>EmailManager</code> + <code>EmailDriverInterface</code></td><td>Shipped</td></tr><tr><td>SMTP driver</td><td>Shipped</td></tr><tr><td>Postmark API driver</td><td>Shipped</td></tr><tr><td>Mailgun API driver</td><td>Shipped</td></tr><tr><td>Amazon SES driver</td><td>Future</td></tr><tr><td>Resend driver</td><td>Future</td></tr><tr><td>SendGrid driver</td><td>Future</td></tr><tr><td>Brevo driver</td><td>Future</td></tr><tr><td>SparkPost driver</td><td>Future</td></tr><tr><td>MailerSend driver</td><td>Future</td></tr></tbody></table><p>New providers must be addable by registering a driver — without scattering provider-specific logic through Controllers, Notifications, or settings UIs.</p><h3 id="central-email-provider-shipped" tabindex="-1">Central email provider (Shipped) <a class="header-anchor" href="#central-email-provider-shipped" aria-label="Permalink to &quot;Central email provider (Shipped)&quot;">​</a></h3><p>Central administrators select the <strong>default outgoing email provider</strong> for the platform (and for tenants that inherit Central mail).</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Provider selection: SMTP, Postmark API, Mailgun API</td><td>Shipped</td></tr><tr><td>Secure credential storage (encrypted secrets at rest)</td><td>Shipped</td></tr><tr><td>From identity (name / address) retained alongside provider config</td><td>Shipped</td></tr><tr><td>Additional providers via the same Central settings surface</td><td>Future</td></tr></tbody></table><h3 id="tenant-email-provider-shipped" tabindex="-1">Tenant email provider (Shipped) <a class="header-anchor" href="#tenant-email-provider-shipped" aria-label="Permalink to &quot;Tenant email provider (Shipped)&quot;">​</a></h3><p>Every tenant has two configuration modes:</p><ol><li><strong>Use Central / System Email Provider</strong> — inherit platform delivery (default).</li><li><strong>Use Custom Email Provider</strong> — tenant-owned white-label delivery.</li></ol><p>When using a custom provider, the tenant may configure <strong>SMTP</strong>, <strong>Postmark API</strong>, or <strong>Mailgun API</strong> (same initial driver set as Central). Credentials remain tenant-scoped, encrypted, and never returned in clear text from admin APIs.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Inherit Central / System provider</td><td>Shipped</td></tr><tr><td>Custom tenant provider (SMTP / Postmark / Mailgun)</td><td>Shipped</td></tr><tr><td>Encrypted tenant secrets + runtime resolution</td><td>Shipped</td></tr></tbody></table><h3 id="email-logs-shipped" tabindex="-1">Email logs (Shipped) <a class="header-anchor" href="#email-logs-shipped" aria-label="Permalink to &quot;Email logs (Shipped)&quot;">​</a></h3><p>Comprehensive, <strong>isolated</strong> email logs for Central and for each Tenant.</p><p>Typical fields:</p><ul><li>Subject, Recipient, CC, BCC</li><li>Provider, Driver, Message ID</li><li>Status, Sent Timestamp, Failure Reason</li><li>Queue Job ID</li><li>Notification / Mailable type</li></ul><p>Filtering:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Scope</th></tr></thead><tbody><tr><td>Status, Provider, Date, User</td><td>Central and Tenant</td></tr><tr><td>Tenant</td><td>Central only</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Central email log store + UI filters</td><td>Shipped</td></tr><tr><td>Tenant email log store + UI filters (tenant-isolated)</td><td>Shipped</td></tr></tbody></table><h3 id="queue-retry-partial-future" tabindex="-1">Queue &amp; retry (Partial / Future) <a class="header-anchor" href="#queue-retry-partial-future" aria-label="Permalink to &quot;Queue &amp; retry (Partial / Future)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Queued email delivery (<code>emails</code> queue + runtime re-apply)</td><td>Shipped</td></tr><tr><td>Retry policies + exponential backoff (<code>email.queue.*</code>)</td><td>Shipped (basic)</td></tr><tr><td>Dead-letter handling</td><td>Future</td></tr><tr><td>Manual resend from logs</td><td>Shipped</td></tr><tr><td>Priority queues</td><td>Future</td></tr></tbody></table><h3 id="provider-capabilities-future" tabindex="-1">Provider capabilities (Future) <a class="header-anchor" href="#provider-capabilities-future" aria-label="Permalink to &quot;Provider capabilities (Future)&quot;">​</a></h3><p>Optional <strong>driver capabilities</strong> — not required of every provider. Drivers advertise what they support; the platform enables features only when the active driver implements them.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Delivery events</td><td>Shipped (webhook-driven)</td></tr><tr><td>Bounce detection</td><td>Shipped (webhook-driven)</td></tr><tr><td>Spam complaints</td><td>Shipped (webhook-driven)</td></tr><tr><td>Open tracking</td><td>Shipped (selectable webhook event)</td></tr><tr><td>Click tracking</td><td>Shipped (selectable webhook event)</td></tr><tr><td>Webhook processing</td><td>Shipped</td></tr><tr><td>Suppression lists</td><td>Future</td></tr></tbody></table><h3 id="email-analytics-future" tabindex="-1">Email analytics (Future) <a class="header-anchor" href="#email-analytics-future" aria-label="Permalink to &quot;Email analytics (Future)&quot;">​</a></h3><p>Dashboards for Central and Tenant (each scoped to its own mail traffic):</p><ul><li>Total Sent, Failed, Delivery Rate, Bounce Rate</li><li>Queue Size, Provider Usage</li><li>Daily Volume, Monthly Volume</li></ul><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Central email analytics dashboard</td><td>Future</td></tr><tr><td>Tenant email analytics dashboard</td><td>Future</td></tr></tbody></table><h3 id="test-email-shipped" tabindex="-1">Test email (Shipped) <a class="header-anchor" href="#test-email-shipped" aria-label="Permalink to &quot;Test email (Shipped)&quot;">​</a></h3><p><strong>Send Test Email</strong> validates provider configuration before (or immediately after) saving credentials. Report:</p><ul><li>Authentication failures</li><li>SMTP / API connectivity</li><li>DNS / configuration issues (where applicable)</li><li>Success / failure response</li><li>Response time</li></ul><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Send Test Email for Central provider config</td><td>Shipped</td></tr><tr><td>Send Test Email for Tenant custom / system provider config</td><td>Shipped</td></tr></tbody></table><h3 id="enterprise-enhancements-enterprise" tabindex="-1">Enterprise enhancements (Enterprise) <a class="header-anchor" href="#enterprise-enhancements-enterprise" aria-label="Permalink to &quot;Enterprise enhancements (Enterprise)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Multiple providers per tenant</td><td>Enterprise</td></tr><tr><td>Automatic provider failover</td><td>Enterprise</td></tr><tr><td>Provider priority</td><td>Enterprise</td></tr><tr><td>Cost-aware routing</td><td>Enterprise</td></tr><tr><td>Regional routing</td><td>Enterprise</td></tr><tr><td>Per-notification provider selection</td><td>Enterprise</td></tr><tr><td>Per-domain provider selection</td><td>Enterprise</td></tr><tr><td>Rate limiting</td><td>Enterprise</td></tr><tr><td>Provider health monitoring</td><td>Enterprise</td></tr></tbody></table><p><strong>Goal:</strong> Production-grade, extensible email delivery for Central and Tenant applications — provider-agnostic at the core, with SMTP as one interchangeable driver, white-label tenant providers, durable logs, and a clear path to reliability, analytics, and enterprise routing without redesigning the platform.</p><hr><h2 id="development-principles" tabindex="-1">Development Principles <a class="header-anchor" href="#development-principles" aria-label="Permalink to &quot;Development Principles&quot;">​</a></h2><p>Every module must:</p><ul><li>Follow the established <a href="/architecture/module-architecture">Module Architecture</a> and <a href="/getting-started/platform-freeze">platform freeze</a></li><li>Be self-contained, own its resources, and declare <a href="/architecture/module-dependencies">dependencies</a> when required</li><li>Remain compatible with independent <a href="/architecture/module-licensing">module licensing</a> and Marketplace activation</li><li>Enforce RBAC permissions</li><li>Maintain tenant isolation</li><li>Integrate with the shared settings framework where applicable</li><li>Generate audit and activity logs where applicable</li><li>Include automated testing (Pest and Playwright)</li><li>Pass manual browser QA</li><li>Update the Developer Guide, User Guide, API documentation, database documentation, testing documentation, and <a href="/changelog/">CHANGELOG</a> before being considered complete — see <a href="/developer-guide/documentation-governance">Documentation Governance</a> (same-PR rule)</li></ul><p>Full checklist: <a href="/developer-guide/module-development">Module Development Standard</a>.</p><hr><h2 id="long-term-vision" tabindex="-1">Long-Term Vision <a class="header-anchor" href="#long-term-vision" aria-label="Permalink to &quot;Long-Term Vision&quot;">​</a></h2><p>Evolve the platform into a modular, enterprise-grade SaaS ERP where organizations subscribe only to the modules they require. Each module integrates with the shared platform foundation while remaining independently licensable, maintainable, and scalable.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/architecture/">Architecture</a></li><li><a href="/architecture/module-architecture">Module Architecture</a></li><li><a href="/architecture/module-dependencies">Module Dependencies</a></li><li><a href="/architecture/module-licensing">Module Licensing</a></li><li><a href="/getting-started/platform-freeze">Platform Architecture Freeze</a></li><li><a href="/developer-guide/module-development">Module Development Standard</a></li><li><a href="/developer-guide/entitlements">Entitlements</a></li><li><a href="/user-guide/leads-overview">Leads</a> · <a href="/user-guide/contacts-overview">Contacts</a> · <a href="/user-guide/companies-overview">Companies</a> · <a href="/user-guide/tasks-overview">Tasks</a> · <a href="/user-guide/todos-overview">ToDos</a> · <a href="/user-guide/vendors-overview">Vendors</a> · <a href="/user-guide/purchase-orders-overview">Purchase Orders</a> · <a href="/user-guide/expenses-overview">Expenses</a></li></ul>',137)])])}const m=t(o,[["render",d]]);export{h as __pageData,m as default};
